R.append((3012658,"बेक्ड मैकरोनी चीज़","बटरनट स्क्वैश से मलाईदार सॉस बनाकर तैयार किया गया, परिवार के इस पसंदीदा व्यंजन का यह स्वादिष्ट रूपांतरण कम नमक, कम पोटैशियम, कम फ़ॉस्फ़ेट और कम प्रोटीन वाला है।","4",None,
["1 बटरनट स्क्वैश (लगभग 600g)","175ml फ़ुल फ़ैट नारियल का दूध","2 छोटे चम्मच डिजॉन सरसों","1 कम नमक वाला सब्ज़ी स्टॉक क्यूब","1 छोटा चम्मच सेब का सिरका","250g मैकरोनी पास्ता","काली मिर्च","100g ब्रेड क्रम्ब्स","50g चेडर चीज़","30g बादाम के फ़्लेक्स","1 बड़ा चम्मच ताज़ा अजमोद (पार्सले) (वैकल्पिक)","200g ब्रोकली"],
["ओवन को 160°C / 140°C फ़ैन / गैस मार्क 3 पर पहले से गरम करें। बटरनट स्क्वैश को आधा काटें और बीज निकाल दें। इसे कटी हुई तरफ़ नीचे की ओर रखकर रोस्टिंग टिन में रखें और 200ml पानी डालें। ओवन में 1 घंटे 30 मिनट बेक करें।","स्क्वैश को थोड़ा ठंडा होने दें, फिर चम्मच से उसका गूदा निकालें। नारियल के दूध के साथ ब्लेंडर में डालकर चिकनी प्यूरी बनाएँ।","प्यूरी बन जाने पर, इसे सॉसपैन में धीमी आँच पर गरम करें। डिजॉन सरसों, सेब का सिरका डालें और स्टॉक क्यूब को चूरकर मिलाएँ। काली मिर्च डालें और ज़रूरत हो तो सॉस में थोड़ा पानी मिलाएँ। गाढ़ा होने तक 20 मिनट धीमी आँच पर पकाएँ।","एक बड़े बर्तन में पानी उबालें। मैकरोनी डालें और 7 मिनट पकाएँ। बेक होते समय यह पकती रहेगी। पास्ता का पानी निथारें और सॉस के साथ मिलाकर ओवन-सेफ़ डिश में डालें।","चीज़ को कद्दूकस करें और ब्रेड क्रम्ब्स, बादाम और बारीक कटे अजमोद (यदि उपयोग कर रहे हों) के साथ मिलाएँ। पास्ता के ऊपर छिड़कें और ओवन में सुनहरा भूरा होने तक 10 मिनट बेक करें।","एक सॉसपैन में पानी उबालें और ब्रोकली डालें। नरम होने तक पकाएँ, पानी निथारें और पास्ता के साथ परोसें।"],
[["शेफ़ का नोट","पारंपरिक व्यंजन का एक नया रूप, मैकरोनी और चीज़ का यह संस्करण एक सुकून देने वाला भोजन है जिसे एक साथ बड़ी मात्रा में बनाकर फ़्रीज़ किया जा सकता है।"],["कार्बोहाइड्रेट","इस व्यंजन में पास्ता और ब्रेड क्रम्ब्स कार्बोहाइड्रेट के मुख्य स्रोत हैं और यह मान उन लोगों के लिए दिया गया है जिन्हें इंसुलिन समायोजन का प्रशिक्षण मिला है।"],["पोटैशियम/फ़ॉस्फ़ेट","इस व्यंजन में सॉस के लिए बटरनट स्क्वैश का उपयोग किया गया है, जो इसे सेहतमंद बनाता है और रेसिपी को कम पोटैशियम वाला रखता है।\nयह व्यंजन फ़ॉस्फ़ेट में कम है, हालाँकि इसमें चीज़ से कुछ फ़ॉस्फ़ेट होता है। यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है, तो इसे इस व्यंजन के साथ लेना सुनिश्चित करें।"],["प्रोटीन","इस व्यंजन में प्रोटीन कम है और यदि आप कम प्रोटीन वाला आहार ले रहे हैं तो यह उपयुक्त है।"],["ग्लूटेन-मुक्त","ग्लूटेन-मुक्त पास्ता, ब्रेड क्रम्ब्स और स्टॉक का उपयोग करें।"],["अधिक सेहतमंद विकल्प","इस व्यंजन में फ़ाइबर बढ़ाने के लिए, मैकरोनी पास्ता की जगह साबुत गेहूँ का पास्ता उपयोग करके देखें।"],["सस्ता विकल्प","यह अपेक्षाकृत सस्ता व्यंजन है। पैसे बचाने के लिए आप अपने खुद के ब्रेड क्रम्ब्स बना सकते हैं।"],["भंडारण","ठंडा होने के बाद, इसे हवाबंद डिब्बे में रखें और फ्रिज में रखें। 3 दिनों के भीतर उपयोग करें और परोसने से पहले अच्छी तरह दोबारा गरम करें। यदि फ़्रीज़ कर रहे हैं, तो चरण 4 के अंत में इसे हवाबंद डिब्बे में हिस्सों में बाँट लें। अच्छी तरह पिघलाएँ, फिर ऊपर की परत का मिश्रण डालें और चरण 5 से पकाना जारी रखें।"],["सुझाव","ताज़ा ब्रेड क्रम्ब्स बनाने के लिए, ब्रेड को टुकड़ों में फाड़ें और ब्लेड लगे फ़ूड प्रोसेसर में डालें। ब्रेड को रुक-रुक कर तब तक चलाएँ जब तक मनचाहे आकार के क्रम्ब्स न बन जाएँ।\nजल्दी के लिए आप पहले से पैक किया हुआ ताज़ा कटा बटरनट स्क्वैश या जमा हुआ स्क्वैश खरीद सकते हैं और चरण 2 से पहले पैकेट के निर्देशों के अनुसार पका सकते हैं।"]],
[]))
R.append((3050711,"चिकन फ़ाजिटा","इस सेहतमंद रेसिपी में कैलोरी की मध्यम मात्रा है और यह प्रोटीन का अच्छा स्रोत है।","4",None,
["200g चिकन ब्रेस्ट, पट्टियों में कटा हुआ","1 लाल शिमला मिर्च, बीज निकालकर कटी हुई","1 पीली शिमला मिर्च, बीज निकालकर कटी हुई","1 प्याज़, छिला और कटा हुआ","1 बड़ा चम्मच जैतून का तेल","400g डिब्बाबंद काली फलियाँ, पानी निथारी और धोई हुई",
["फ़ाजिटा मसाला","1 छोटा चम्मच तीखा लाल मिर्च पाउडर"],["फ़ाजिटा मसाला","2 छोटे चम्मच मीठी स्मोक्ड पैपरिका"],["फ़ाजिटा मसाला","1 छोटा चम्मच पिसा जीरा"],["फ़ाजिटा मसाला","1 छोटा चम्मच लहसुन पाउडर"],["फ़ाजिटा मसाला","1 छोटा चम्मच सूखी अजवायन (ओरेगैनो)"],
["परोसने के लिए","80g खट्टी क्रीम"],["परोसने के लिए","160g ग्वाकामोले (या आप इसे खुद बना सकते हैं, सुझाव वाला भाग देखें)"],["परोसने के लिए","4 x मैदे की टॉर्टिला"],
["साइड सलाद","200g मिश्रित सलाद की पत्तियाँ"],["साइड सलाद","6-8 चेरी टमाटर, आधे कटे हुए"],["साइड सलाद","½ खीरा, छोटे टुकड़ों में कटा हुआ"],
["ड्रेसिंग","1 बड़ा चम्मच जैतून का तेल"],["ड्रेसिंग","2 छोटे चम्मच सेब का सिरका"],["ड्रेसिंग","2 छोटे चम्मच डिजॉन सरसों"],["ड्रेसिंग","थोड़ी पिसी काली मिर्च"]],
["सभी सामग्री को मिलाकर फ़ाजिटा मसाला बनाएँ। चिकन की पट्टियाँ और जैतून का तेल डालें और सब कुछ मिलने तक मिलाएँ।","एयर फ़्रायर को रोस्टिंग सेटिंग में 190°C पर पहले से गरम करें। सब्ज़ियों और फलियों को चिकन के साथ मिलाएँ और 15 मिनट पकाएँ, पकाते समय बास्केट को दो बार हिलाएँ। यदि चाहें तो इस रेसिपी को चूल्हे पर फ्राइंग पैन में भी पकाया जा सकता है। चिकन को जैतून के तेल में हर तरफ़ से भूरा होने तक पैन-फ़्राई करें, फिर बाकी सामग्री डालें और मध्यम आँच पर 15 मिनट पकाएँ।","सभी सामग्री को एक कटोरे में डालकर और फेंटकर सलाद ड्रेसिंग बनाएँ। परोसने से ठीक पहले इस ड्रेसिंग को कटे हुए खीरे, सलाद की पत्तियों और टमाटरों में डालें और अच्छी तरह मिलाएँ।","चिकन फ़ाजिटा का मिश्रण पक जाने पर इसे टॉर्टिला, खट्टी क्रीम और ग्वाकामोले के साथ परोसें। तैयार सलाद को साथ में परोसें।"],
[["शेफ़ का नोट","यह झटपट और आसान रेसिपी सप्ताह के बीच के रात के खाने के लिए एकदम सही है।"],["बच्चों के लिए परोसे की मात्रा का मार्गदर्शन","परोसे की मात्रा वयस्कों के हिस्से पर आधारित है। बच्चों के लिए यह एक मार्गदर्शिका है:\nछोटा बच्चा (आयु 1-4): वयस्क हिस्से का ¼\nबच्चा (आयु 5-9): वयस्क हिस्से का ½\nबड़ा बच्चा (आयु 10-13): वयस्क हिस्से का ¾\nकिशोर (14+): 1 वयस्क हिस्सा\nकुछ बच्चों की भूख दूसरों से अधिक होती है। यदि आपको लगता है कि सुझाई गई मात्रा बहुत अधिक या कम है, तो आपके बच्चे के हिस्से को उसके सामान्य आहार के अनुसार बदलना पड़ सकता है। यदि आपके बच्चे को पोटैशियम या फ़ॉस्फ़ेट को संभालने में कठिनाई हुई है, तो परोसे की मात्रा बढ़ाने से पहले हम अपने आहार विशेषज्ञ से बात करने की सलाह देते हैं।"],["कार्बोहाइड्रेट","इस रेसिपी में टॉर्टिला कार्बोहाइड्रेट का मुख्य स्रोत हैं, और यह मान उन लोगों के लिए दिया गया है जिन्हें इंसुलिन समायोजन का प्रशिक्षण मिला है।"],["पोटैशियम/फ़ॉस्फ़ेट","एवोकाडो जैसी कुछ उच्च पोटैशियम वाली सामग्री के उपयोग के बावजूद, सामग्री की मात्रा, पकाने की विधि और परोसे के आकार का पालन करने पर यह रेसिपी पोटैशियम में कम है। इसलिए, यह उन लोगों के लिए उपयुक्त है जिन्हें अपने आहार में पोटैशियम कम करने की सलाह दी गई है। यह रेसिपी फ़ॉस्फ़ेट में भी कम है, हालाँकि इसमें कुछ फ़ॉस्फ़ेट होता है, जो मुख्य रूप से चिकन, टॉर्टिला रैप और चीज़ से आता है, इसलिए यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है, तो इसे निर्देशानुसार लें।\nफ़ॉस्फ़ेट को और कम करने के लिए आप कुछ या सारे मांस की जगह पौधे-आधारित विकल्प, जैसे 250g डिब्बाबंद काली फलियाँ-पानी निथारी हुई, लेने पर विचार कर सकते हैं। हालाँकि, इससे रेसिपी में प्रोटीन की मात्रा भी घटेगी।"],["प्रोटीन","यह रेसिपी प्रोटीन का स्रोत है। यदि आपको कम प्रोटीन खाने की सलाह दी गई है, तो चिकन को घटाकर 100g करने और फलियों को बढ़ाकर 200g-250g करने पर विचार करें।"],["ऊर्जा","यदि आपको वज़न बढ़ाना है, आपका बढ़ता बच्चा है जिसे अधिक कैलोरी चाहिए, या भूख कम लगती है, तो आप चिकन पकाने के लिए एक बड़ा चम्मच अतिरिक्त तेल का उपयोग कर सकते हैं। कैलोरी बढ़ाने के लिए अतिरिक्त मांस या चीज़ डालने से रेसिपी में फ़ॉस्फ़ेट की मात्रा बढ़ेगी।"],["शाकाहारी","चिकन की जगह 200g टेम्पेह या टोफ़ू का उपयोग करने पर विचार करें।"],["वीगन","दूध-रहित खट्टी क्रीम के विकल्पों का उपयोग करने पर विचार करें।"],["ग्लूटेन-मुक्त","ग्लूटेन-मुक्त टॉर्टिला का उपयोग करें।"],["अधिक सेहतमंद विकल्प","साबुत गेहूँ के टॉर्टिला रैप का उपयोग करें।"],["सस्ता विकल्प","वनस्पति/सूरजमुखी तेल का उपयोग करें।\nअपनी रसोई में मौजूद कोई भी सिरका उपयोग करें।\nयदि सभी मसाले हाथ में न हों, तो फ़ाजिटा मसाला मिक्स का उपयोग करने पर विचार करें (बिना अतिरिक्त नमक वाले संस्करण देखें)।\nमिश्रित सलाद की पत्तियों की जगह आइसबर्ग लेट्यूस का उपयोग करें।\nअपनी पसंद की कोई भी चिकनी सरसों का उपयोग करें।"],["भंडारण","इस व्यंजन को ताज़ा बना हुआ खाना सबसे अच्छा रहता है। बची हुई ड्रेसिंग को फ्रिज में एक सप्ताह तक रखा जा सकता है।"],["सुझाव","इसे विकल्प के रूप में टैको शेल या चावल के साथ परोसा जा सकता है।"],["सुझाव: अपना ग्वाकामोले बनाना","आप अपना ग्वाकामोले खुद बना सकते हैं:\n1 पका एवोकाडो – छिला हुआ, गुठली निकाली हुई और काँटे से मसला हुआ\n1 लाल मिर्च – बीज निकालकर बारीक कटी हुई\n1 नीबू का रस\nताज़ा धनिया की छोटी मुट्ठी भर – बारीक कटी हुई\n1 छोटा लाल प्याज़ – छिला और बारीक कटा हुआ\nसभी सामग्री को एक साथ मिलाएँ।"]],
[]))
R.append((3067106,"ब्रोकली और फूलगोभी पास्ता बेक","जल्दी भोजन के लिए, इस रेसिपी को दिन में पहले तैयार किया जा सकता है और बाद में ओवन में पकाया जा सकता है (ध्यान रखें कि इस बीच यह फ्रिज में रहे)।","2",None,
["150g सूखा पास्ता – कोई भी आकार","200g ब्रोकली के फूल, ताज़े या जमे हुए","200g फूलगोभी के फूल, ताज़े या जमे हुए","200g क्रीम चीज़","काली मिर्च","1 छोटा चम्मच सूखी मिश्रित जड़ी-बूटियाँ","15g तेज़ चेडर, कद्दूकस किया हुआ","30g ब्रेड क्रम्ब्स"],
["ओवन को 165°C पर पहले से गरम करें। एक बर्तन में पानी उबालें और पास्ता डालकर 5 मिनट पकाएँ। ब्रोकली और फूलगोभी को बर्तन में डालें और सब कुछ पकने तक 8 मिनट और पकाएँ, फिर पानी निथार लें।","एक कटोरे में क्रीम चीज़ में काली मिर्च और सूखी जड़ी-बूटियाँ मिलाएँ।","पास्ता और सब्ज़ियों को बेकिंग डिश में डालें और क्रीम चीज़ का मिश्रण मिलाएँ। ऊपर से ब्रेड क्रम्ब्स और चेडर चीज़ छिड़कें। सुनहरा भूरा होने तक 30 मिनट पकाएँ।","ओवन से निकालें और परोसने से पहले 5 मिनट रहने दें।"],
[["शेफ़ का नोट","यह एक भरपूर, मलाईदार रात का खाना है, जिसमें ऊर्जा अधिक है लेकिन नमक, फ़ॉस्फ़ेट और पोटैशियम कम हैं।"],["कार्बोहाइड्रेट","इस मुख्य भोजन में पास्ता कार्बोहाइड्रेट का मुख्य स्रोत है। यह मान उन लोगों के लिए दिया गया है जिन्हें इंसुलिन समायोजन का प्रशिक्षण मिला है।"],["पोटैशियम/फ़ॉस्फ़ेट","यह व्यंजन पोटैशियम में कम है, क्योंकि प्रति व्यक्ति मात्रा को सावधानी से मापा गया है। यदि आपको कम पोटैशियम वाला आहार लेने की सलाह दी गई है, तो बताई गई मात्रा का पालन करना सुनिश्चित करें। यह रेसिपी फ़ॉस्फ़ेट में कम है, हालाँकि इसमें कुछ फ़ॉस्फ़ेट होता है, इसलिए यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किए गए हैं, तो उन्हें इस व्यंजन के साथ लेना सुनिश्चित करें।"],["प्रोटीन","प्रोटीन चेडर और क्रीम चीज़ से मिलता है। प्रोटीन कम करने के लिए, आप वीगन विकल्प उपयोग कर सकते हैं जिनमें अक्सर डेयरी स्रोतों से कम प्रोटीन होता है।"],["भंडारण","जल्दी भोजन के लिए, इस रेसिपी को दिन में पहले तैयार किया जा सकता है और बाद में ओवन में पकाया जा सकता है (ध्यान रखें कि इस बीच यह फ्रिज में रहे)। बचा हुआ फ्रिज में 2 दिन तक रहता है।"]],
[]))
R.append((3121590,"चना चाट","यह उच्च प्रोटीन, कम पोटैशियम वाला नाश्ता है जो डायलिसिस पर रहने वाले व्यक्ति के लिए उपयुक्त है, लेकिन इतना स्वादिष्ट है कि हर कोई इसे खाना चाहेगा।","3",None,
["1 बड़ा वाइन टमाटर","½ लाल प्याज़","80g खीरा","240g छोले, पानी में डिब्बाबंद","1 छोटा चम्मच चना चाट मसाला","3 बड़े चम्मच नींबू का रस",["परोसने के लिए","2 बड़े चम्मच ग्रीक योगर्ट"],["परोसने के लिए","1 हरी मिर्च"]],
["सब्ज़ियाँ तैयार करने के लिए, टमाटर, प्याज़ और खीरे को छोटे, एक जैसे आकार के टुकड़ों में काटें और कटोरे में डालें। मिर्च को काटें और बाद के लिए अलग रख दें।","छोले का पानी निथारें और टमाटर, प्याज़ और खीरे के मिश्रण में डालें। चलाएँ।","नींबू का रस और चना चाट मसाला डालें। अच्छी तरह मिलाने के लिए चलाएँ।","मिश्रण को तीन कटोरियों में बाँटें। ऊपर से योगर्ट डालें और स्वादानुसार कटी हुई मिर्च डालें।"],
[["शेफ़ का नोट","चना चाट चटपटी, ताज़ी और बनाने में आसान है, जिसमें पकाने की ज़रूरत नहीं होती। यह नमकीन संस्करण किडनी-अनुकूल है और उन लोगों के लिए बनाया गया है जो रमज़ान के दौरान कुछ पारंपरिक खाना चाहते हैं।"],["कार्बोहाइड्रेट","इस व्यंजन में योगर्ट, छोले, टमाटर और खीरा सभी कार्बोहाइड्रेट के स्रोत हैं। कुल कार्बोहाइड्रेट मान उन लोगों के लिए दिया गया है जिन्हें इंसुलिन समायोजन का प्रशिक्षण मिला है।"],["पोटैशियम/फ़ॉस्फ़ेट","कच्ची सब्ज़ियों में पोटैशियम अधिक होता है, लेकिन यदि आप बताए गए परोसे के आकार का पालन करते हैं, तो यह व्यंजन कुल मिलाकर पोटैशियम में कम है। प्रत्येक परोसे में फल और सब्ज़ियों के दो हिस्से होते हैं, इसलिए यदि आप दिन के बाकी समय में और खाते हैं तो ध्यान रखें।\nयदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किए गए हैं, तो उन्हें इस व्यंजन के साथ लेना सुनिश्चित करें।"],["प्रोटीन","छोले प्रोटीन का अच्छा स्रोत हैं, जो इसे उच्च प्रोटीन वाला नाश्ता बनाते हैं, जो डायलिसिस पर रहने वालों के लिए आदर्श है।"],["वीगन","डेयरी-मुक्त योगर्ट का उपयोग करें।"],["अधिक सेहतमंद विकल्प","इस व्यंजन में वसा की मात्रा कम करने के लिए, आप इसे कम वसा वाले योगर्ट के साथ या योगर्ट के बिना परोस सकते हैं।"],["भंडारण","चना चाट को हवाबंद डिब्बे में रखकर फ्रिज में दो दिन तक रखा जा सकता है।"]],
[]))
